code { font-family: Source Code Pro; }
td, th { border: 1px solid #cbcbcb; padding: 2px; vertical-align: top; }
th { background-color: #f2f2f2; text-align: left; }
body { margin: 0; background-color: #f9f9f9; border-color: #bbb; color: #333; text-shadow: 0 1px 0 #f3f3f3; }
main, footer { padding: 0 1em; }
.pure-table th { border-width: 0 0 1px 1px; border-color: #cbcbcb; }
.pure-table tr:last-child th { border-bottom: none; }
.pure-table th, .pure-table td { font-size: 14px; }
.pure-menu-link, a:link { color: #205081; }
a.pure-menu-link:hover { background-color: #ddd; outline: 1px solid #cbcbcb; }
a.pure-menu-link:focus { background-color: #ddd; }
a:hover, a:focus { text-decoration: none; }
*:focus { outline: 2px solid #205081; }
nav { background-color: #f2f2f2; border: 1px solid #cbcbcb; }
footer { background-color: #f2f2f2; border: 1px solid #cbcbcb; margin-top: 1em; text-align: center; font-weight: bold; padding-bottom: 1.4em; }
table.layout td { border: none; }
pre { white-space: pre-wrap;       /* css-3 */ white-space: -moz-pre-wrap;  /* Mozilla, since 1999 */ white-space: -pre-wrap;      /* Opera 4-6 */ white-space: -o-pre-wrap;    /* Opera 7 */ word-wrap: break-word;       /* Internet Explorer 5.5+ */ }
img { max-width: 100%; height: auto; }
.pure-table { overflow-x: auto; display: block; border: none; }
.pure-table tr:first-child th { border-bottom: 1px solid #cbcbcb; }
table.dataTable.no-footer { border-bottom: none; }
#toggles { font-size: 14px; float: left; }
#toggles label { display: block; }
.pure-menu-link { padding: .4em .5em; }
.pure-menu-list { margin-left: 2px; }
#skip-link { position: absolute; top: -25px; left: 0px; z-index: 1; padding: .2em; font-size: 13px; font-weight: bold; margin: 3px; background-color: white; }
#skip-link:focus { position: absolute; left: 0px; top: 0px; transition: top .3s ease-in, background .5s linear; }
form#contact label, form#contact input[type=submit] { display: block; margin-top: .5em; margin-bottom: .1em; }
i.fa-home { margin-left: -5px; }
em.errorMessage { color: #e80000; margin-top: 5px; display: block; }
[aria-invalid=true] { outline: 2px solid #e80000; }
label { cursor: pointer; }
input::-webkit-input-placeholder, textarea::-webkit-input-placeholder {
	color:#696969;
	font-weight: normal;
}
input::-moz-placeholder, textarea::-moz-placeholder {
	color:#696969;
	font-weight: normal;
}
input:-moz-placeholder, textarea:-moz-placeholder {   /* Older versions of Firefox */
	color:#696969;
	font-weight: normal;
}
input:-ms-input-placeholder, textarea:-ms-input-placeholder { 
	color:#696969;
	font-weight: normal;
}
input[placeholder], textarea[placeholder]  {
    font-weight: bold;
 }


@media screen and (max-width: 640px) {
}



@media (prefers-color-scheme: dark) {
	body { margin: 0; border-color: #bbb; color: #eee; background: black; text-shadow: none; }


	a:link {
	  color: lightskyblue;
	}
	a:visited {color: lightsteelblue;}

	a.pure-menu-link:hover { background-color: black; outline: 1px solid #cbcbcb; }
	a.pure-menu-link:focus { background-color: black; }
	a:hover, a:focus { text-decoration: none; }
	*:focus { outline: 2px solid #205081; }
	nav { background-color: black; border: 1px solid #cbcbcb; }
	footer { background-color: black; border: 1px solid #cbcbcb; margin-top: 1em; text-align: center; font-weight: bold; padding-bottom: 1.4em; }

	th { background-color: black; text-align: left; }



  }

